const frame = msg.payload || msg;
let canId = frame.canid & 0x1FFFFFFF;
const data = frame.data || [];

// Only process PCS_FAULT_TIMEOUT_GRP_2 (0x66B979x)
if ((canId & 0xFFFFFFF0) !== 0x66B9790) {
    return null;
}

// Helper function to get bit value
function getBit(buf, bitIndex) {
    const byteIndex = Math.floor(bitIndex / 8);
    const bitOffset = bitIndex % 8;
    if (byteIndex >= buf.length) return false;
    return ((buf[byteIndex] >> bitOffset) & 0x01) === 1;
}

let state = {
    kind: "PcsFaultGrp2State",
    version: 1,
    timestampUtc: new Date().toISOString(),

    // ==================== Byte 0 (Bit 0-7) ====================
    pcs_preRelCloseFail: getBit(data, 0),        // Bit 0 - Pre Relay Close Fail
    pcs_preRelOpenFail: getBit(data, 1),         // Bit 1 - Pre Relay Open Fail
    pcs_preRelStClose: getBit(data, 2),          // Bit 2 - Pre Relay Stuck Close
    pcs_preRelStOpen: getBit(data, 3),           // Bit 3 - Pre Relay Stuck Open
    pcs_mainRelCloseFail: getBit(data, 4),       // Bit 4 - Main Relay Close Fail
    pcs_mainRelOpenFail: getBit(data, 5),        // Bit 5 - Main Relay Open Fail
    pcs_mainRelStClose: getBit(data, 6),         // Bit 6 - Main Relay Stuck Close
    pcs_mainRelNum: getBit(data, 7),             // Bit 7 - Main Relay Number

    // ==================== Byte 1 (Bit 8-15) ====================
    pcs_acMainAdhFault: getBit(data, 8),         // Bit 8 - AC Main Adhesion Fault
    pcs_dcRelOpenFault: getBit(data, 9),         // Bit 9 - DC Relay Open Fault
    pcs_acMainOpenFault: getBit(data, 10),       // Bit 10 - AC Main Open Fault
    pcs_invAOvFault: getBit(data, 11),           // Bit 11 - Inverter A Over Voltage Fault
    pcs_invBOvFault: getBit(data, 12),           // Bit 12 - Inverter B Over Voltage Fault
    pcs_invCOvFault: getBit(data, 13),           // Bit 13 - Inverter C Over Voltage Fault
    pcs_gridIslandFault: getBit(data, 14),       // Bit 14 - Grid Island Fault
    pcs_sysResonFault: getBit(data, 15),         // Bit 15 - System Resonance Fault

    // ==================== Byte 2 (Bit 16-23) ====================
    pcs_swOvOcFault: getBit(data, 16),           // Bit 16 - SW Over/Over Current Fault
    pcs_hvCrossToFault: getBit(data, 17),        // Bit 17 - HV Cross Timeout Fault
    pcs_invAUvFault: getBit(data, 18),           // Bit 18 - Inverter A Under Voltage Fault
    pcs_invBUvFault: getBit(data, 19),           // Bit 19 - Inverter B Under Voltage Fault
    pcs_invCUvFault: getBit(data, 20),           // Bit 20 - Inverter C Under Voltage Fault
    pcs_offNoSyncFault: getBit(data, 21),        // Bit 21 - Off No Sync Fault
    pcs_offShortFault: getBit(data, 22),         // Bit 22 - Off Short Fault
    pcs_lvCrossToFault: getBit(data, 23),        // Bit 23 - LV Cross Timeout Fault

    // ==================== Byte 3 (Bit 24-31) ====================
    pcs_msg1Timeout: getBit(data, 24),           // Bit 24 - PCS MSG1 Timeout
    pcs_msg2Timeout: getBit(data, 25),           // Bit 25 - PCS MSG2 Timeout
    pcs_powerTimeout: getBit(data, 26),          // Bit 26 - Power Timeout
    pcs_moduleOpModeTout: getBit(data, 27),      // Bit 27 - Module Operation Mode Timeout
    pcs_setOngridModeTout: getBit(data, 28),     // Bit 28 - Set On-Grid Mode Timeout
    pcs_setOffgridFreqTout: getBit(data, 29),    // Bit 29 - Set Off-Grid Frequency Timeout
    pcs_setOffgridVoltTout: getBit(data, 30),    // Bit 30 - Set Off-Grid Voltage Timeout
    pcs_setPcsTout: getBit(data, 31),            // Bit 31 - Set PCS Timeout

    // ==================== Byte 4 (Bit 32-39) ====================
    pcs_setPwrIndepTout: getBit(data, 32),       // Bit 32 - Set Power Independent Timeout
    pcs_setModHostTout: getBit(data, 33),        // Bit 33 - Set Module Host Timeout
    pcs_modCurrSrcParTout: getBit(data, 34),     // Bit 34 - Module Current Source Par Timeout
    pcs_setDehumidTout: getBit(data, 35),        // Bit 35 - Set Dehumidify Timeout
    pcs_setNumParMdiTout: getBit(data, 36),      // Bit 36 - Set Number Par MDI Timeout
    pcs_setAPhActPwrTout: getBit(data, 37),      // Bit 37 - Set A Phase Active Power Timeout
    pcs_setAPhReaPwrTout: getBit(data, 38),      // Bit 38 - Set A Phase Reactive Power Timeout
    pcs_setBPhActPwrTout: getBit(data, 39),      // Bit 39 - Set B Phase Active Power Timeout

    // ==================== Byte 5 (Bit 40-47) ====================
    pcs_setBPhReaPwrTout: getBit(data, 40),      // Bit 40 - Set B Phase Reactive Power Timeout
    pcs_setCPhActPwrTout: getBit(data, 41),      // Bit 41 - Set C Phase Active Power Timeout
    pcs_setCPhReaPwrTout: getBit(data, 42),      // Bit 42 - Set C Phase Reactive Power Timeout
    pcs_yearTout: getBit(data, 43),              // Bit 43 - Year Timeout
    pcs_monthTout: getBit(data, 44),             // Bit 44 - Month Timeout
    pcs_dayTout: getBit(data, 45),               // Bit 45 - Day Timeout
    pcs_hourTout: getBit(data, 46),              // Bit 46 - Hour Timeout
    pcs_minuteTout: getBit(data, 47),            // Bit 47 - Minute Timeout

    // ==================== Byte 6 (Bit 48-55) ====================
    pcs_secondTout: getBit(data, 48),            // Bit 48 - Second Timeout
    pcs_setMaxChgPwrTout: getBit(data, 49),      // Bit 49 - Set Max Charge Power Timeout
    pcs_setMaxDchPwrTout: getBit(data, 50),      // Bit 50 - Set Max Discharge Power Timeout
    pcs_setMaxChgCurrTout: getBit(data, 51),     // Bit 51 - Set Max Charge Current Timeout
    pcs_setMaxDchCurrTout: getBit(data, 52),     // Bit 52 - Set Max Discharge Current Timeout
    pcs_setDcBusVTout: getBit(data, 53),         // Bit 53 - Set DC Bus Voltage Timeout
    pcs_setDcSrcBusVTout: getBit(data, 54),      // Bit 54 - Set DC Source Bus Voltage Timeout
    pcs_setInsulEnTout: getBit(data, 55),        // Bit 55 - Set Insulation Enable Timeout

    // ==================== Byte 7 (Bit 56-63) ====================
    pcs_gridOverfProtTout: getBit(data, 56),     // Bit 56 - Grid Over Frequency Protection Timeout
    pcs_gridUnderfProtTout: getBit(data, 57),    // Bit 57 - Grid Under Frequency Protection Timeout
    pcs_islOverfProtTout: getBit(data, 58),      // Bit 58 - Island Over Frequency Protection Timeout
    pcs_islUnderfProtTout: getBit(data, 59),     // Bit 59 - Island Under Frequency Protection Timeout
    pcs_batOvProtTout: getBit(data, 60),         // Bit 60 - Battery Over Voltage Protection Timeout
    pcs_batUvProtTout: getBit(data, 61),         // Bit 61 - Battery Under Voltage Protection Timeout
    pcs_busOvProtTout: getBit(data, 62),         // Bit 62 - Bus Over Voltage Protection Timeout
    pcs_busUvProtTout: getBit(data, 63)          // Bit 63 - Bus Under Voltage Protection Timeout
};

// ==================== Derived Fields ====================
const allFaultFlags = [
    'pcs_preRelCloseFail', 'pcs_preRelOpenFail', 'pcs_preRelStClose', 'pcs_preRelStOpen',
    'pcs_mainRelCloseFail', 'pcs_mainRelOpenFail', 'pcs_mainRelStClose', 'pcs_mainRelNum',
    'pcs_acMainAdhFault', 'pcs_dcRelOpenFault', 'pcs_acMainOpenFault', 'pcs_invAOvFault',
    'pcs_invBOvFault', 'pcs_invCOvFault', 'pcs_gridIslandFault', 'pcs_sysResonFault',
    'pcs_swOvOcFault', 'pcs_hvCrossToFault', 'pcs_invAUvFault', 'pcs_invBUvFault',
    'pcs_invCUvFault', 'pcs_offNoSyncFault', 'pcs_offShortFault', 'pcs_lvCrossToFault',
    'pcs_msg1Timeout', 'pcs_msg2Timeout', 'pcs_powerTimeout', 'pcs_moduleOpModeTout',
    'pcs_setOngridModeTout', 'pcs_setOffgridFreqTout', 'pcs_setOffgridVoltTout', 'pcs_setPcsTout',
    'pcs_setPwrIndepTout', 'pcs_setModHostTout', 'pcs_modCurrSrcParTout', 'pcs_setDehumidTout',
    'pcs_setNumParMdiTout', 'pcs_setAPhActPwrTout', 'pcs_setAPhReaPwrTout', 'pcs_setBPhActPwrTout',
    'pcs_setBPhReaPwrTout', 'pcs_setCPhActPwrTout', 'pcs_setCPhReaPwrTout', 'pcs_yearTout',
    'pcs_monthTout', 'pcs_dayTout', 'pcs_hourTout', 'pcs_minuteTout',
    'pcs_secondTout', 'pcs_setMaxChgPwrTout', 'pcs_setMaxDchPwrTout', 'pcs_setMaxChgCurrTout',
    'pcs_setMaxDchCurrTout', 'pcs_setDcBusVTout', 'pcs_setDcSrcBusVTout', 'pcs_setInsulEnTout',
    'pcs_gridOverfProtTout', 'pcs_gridUnderfProtTout', 'pcs_islOverfProtTout', 'pcs_islUnderfProtTout',
    'pcs_batOvProtTout', 'pcs_batUvProtTout', 'pcs_busOvProtTout', 'pcs_busUvProtTout'
];

let activeFaults = [];
allFaultFlags.forEach(flag => {
    if (state[flag] === true) activeFaults.push(flag);
});

state.pcs_hasFaultGrp2 = activeFaults.length > 0;
state.pcs_activeFaultsGrp2 = activeFaults;
state.pcs_activeFaultCountGrp2 = activeFaults.length;

flow.set("pcsFaultGrp2State", state);
msg.payload = state;
return msg;

var state = flow.get("pcsFaultGrp2State");
if (state) {
    msg.payload = state;
    return msg;
}
msg.payload = { error: "No data yet" };
return msg;
